/* Read nbits bits of buf as one insn.  On success all of them were used and the strings of octets in *out point into buf (or, when they start inside a byte, into the arena). */
static bool bnf_read (const uint8_t *buf, size_t nbits, insn_t *out,
                     char *err, size_t errsz, size_t *fail_bit) {
    bnf_p p;
    memset (&p, 0, sizeof p);
    p.buf = buf;  p.nbits = nbits;  p.len = (nbits + 7) / 8;
    memset (out, 0, sizeof *out);
    if (!parse_rule_insn (&p, out)) goto bad;
    if (p.bit != nbits) {
        char t[64];
        p.failed = 0;
        snprintf (t, sizeof t, "%zu bit(s) left over after the message", nbits - p.bit);
        bnf_fail (&p, p.bit, "insn", t);
        goto bad;
    }
    return true;
bad:
    if (fail_bit) *fail_bit = p.fail_bit;
    if (err && errsz) snprintf (err, errsz, "%s", p.msg);
    return false;
}
bool parse_bits (const uint8_t *buf, size_t nbits, insn_t *out,
                 char *err, size_t errsz, size_t *at) {
    size_t fb = 0;
    char m[256];
    bool ok = bnf_read (buf, nbits, out, m, sizeof m, &fb);
    if (!ok) {
        if (at) *at = fb / 8;
        if (err && errsz) snprintf (err, errsz, "octet %zu: %s", fb / 8, m);
    }
    return ok;
}
bool parse_bytes (const uint8_t *buf, size_t len, insn_t *out,
                  char *err, size_t errsz, size_t *at) {
    return parse_bits (buf, len * 8, out, err, errsz, at);
}

/* Write *in as bits.  *nbits is the number of bits it takes, even when buf is NULL or too small (then false, as snprintf's count).  A value that does not fit its field, or does not agree with a length or tag field, is an error, not a guess. */
bool emit_bits (const insn_t *in, uint8_t *buf, size_t cap, size_t *nbits,
                char *err, size_t errsz) {
    bnf_w w;
    memset (&w, 0, sizeof w);
    w.buf = buf;  w.cap = cap;
    (void)bnf_swap;  (void)bnf_grow;  (void)bnf_take_rest;
    if (!emit_rule_insn (&w, in)) goto bad;
    if (nbits) *nbits = w.bit;
    if (buf && (w.bit + 7) / 8 > cap) {
        bnf_wfail (&w, "insn", "the buffer is too small");
        goto bad;
    }
    return true;
bad:
    if (nbits) *nbits = w.bit;
    if (err && errsz) snprintf (err, errsz, "%s", w.msg);
    return false;
}
/* The same, for a message that is whole octets. */
bool emit_bytes (const insn_t *in, uint8_t *buf, size_t cap, size_t *n,
                 char *err, size_t errsz) {
    size_t nb = 0;
    bool ok = emit_bits (in, buf, cap, &nb, err, errsz);
    if (ok && (nb & 7)) {
        if (err && errsz) snprintf (err, errsz, "insn: the message does not end on an octet boundary");
        ok = false;
    }
    if (n) *n = (nb + 7) / 8;
    return ok;
}

